			inputMountain[i] = br.readLine();
	}

	public void stringToInteger(){
		int i;
		for(i=0;i<10;i++)
			mountain[i] = Integer.parseInt(inputMountain[i]);
	}

	public void sortMountain(){
		int i,j,t;

		for(i=0;i<9;i++){
			for(j=9;j>i;j--){
				if(mountain[j]<mountain[j-1]){
					t = mountain[j];
					mountain[j] = mountain[j-1];
					mountain[j-1] = t;
				}
			}
		}
	}

	public void output(){
		int i;
		for(i=9;i>6;i--)
			System.out.println(mountain[i]);
	}
