				if(mountain[j]<mountain[j-1]){
					t = mountain[j];
					mountain[j] = mountain[j-1];
					mountain[j-1] = t;
				}
			}
		}
	}

	public void output(){
		int i;
		for(i=9;i>6;i--)
			System.out.println(mountain[i]);
